	function automatic [63:0] ara_pkg_vaddr;
		input reg [4:0] vid;
		input reg signed [31:0] NrLanes;
		input reg signed [31:0] vlen;
		reg signed [31:0] vlenb;
		begin
			vlenb = vlen / 8;
			ara_pkg_vaddr = vid * ((vlenb / NrLanes) / 8);
		end
	endfunction
	localparam axi_pkg_BURST_INCR = 2'b01;
	localparam axi_pkg_BURST_FIXED = 2'b00;
	localparam axi_pkg_BURST_WRAP = 2'b10;
	function automatic [127:0] axi_pkg_aligned_addr;
		input reg [127:0] addr;
		input reg [2:0] size;
		axi_pkg_aligned_addr = (addr >> size) << size;
	endfunction
	function automatic [15:0] axi_pkg_num_bytes;
		input reg [2:0] size;
		axi_pkg_num_bytes = 1 << size;
	endfunction
	function automatic [127:0] axi_pkg_wrap_boundary;
		input reg [127:0] addr;
		input reg [2:0] size;
		input reg [7:0] len;
		reg [127:0] wrap_addr;
		begin
			(* full_case, parallel_case *)
			case (len)
				4'b0001: wrap_addr = (addr >> ($unsigned(size) + 1)) << ($unsigned(size) + 1);
				4'b0011: wrap_addr = (addr >> ($unsigned(size) + 2)) << ($unsigned(size) + 2);
				4'b0111: wrap_addr = (addr >> ($unsigned(size) + 3)) << ($unsigned(size) + 3);
				4'b1111: wrap_addr = (addr >> ($unsigned(size) + 4)) << ($unsigned(size) + 4);
				default: wrap_addr = 1'sb0;
			endcase
			axi_pkg_wrap_boundary = wrap_addr;
		end
	endfunction
	function automatic [127:0] axi_pkg_beat_addr;
		input reg [127:0] addr;
		input reg [2:0] size;
		input reg [7:0] len;
		input reg [1:0] burst;
		input reg [15:0] i_beat;
		reg [127:0] ret_addr;
		reg [127:0] wrp_bond;
		begin
			ret_addr = addr;
			wrp_bond = 1'sb0;
			if (burst == axi_pkg_BURST_WRAP)
				wrp_bond = axi_pkg_wrap_boundary(addr, size, len);
			if ((i_beat != 0) && (burst != axi_pkg_BURST_FIXED)) begin
				ret_addr = axi_pkg_aligned_addr(addr, size) + (i_beat * axi_pkg_num_bytes(size));
				if ((burst == axi_pkg_BURST_WRAP) && (ret_addr >= (wrp_bond + (axi_pkg_num_bytes(size) * (len + 1)))))
					ret_addr = ret_addr - (axi_pkg_num_bytes(size) * (len + 1));
			end
			axi_pkg_beat_addr = ret_addr;
		end
	endfunction
	function automatic signed [15:0] sv2v_cast_16_signed;
		input reg signed [15:0] inp;
		sv2v_cast_16_signed = inp;
	endfunction
	function automatic [15:0] axi_pkg_beat_lower_byte;
		input reg [127:0] addr;
		input reg [2:0] size;
		input reg [7:0] len;
		input reg [1:0] burst;
		input reg [15:0] strobe_width;
		input reg [15:0] i_beat;
		reg [127:0] _addr;
		begin
			_addr = axi_pkg_beat_addr(addr, size, len, burst, i_beat);
			axi_pkg_beat_lower_byte = sv2v_cast_16_signed(_addr - ((_addr / strobe_width) * strobe_width));
		end
	endfunction
	function automatic [15:0] axi_pkg_beat_upper_byte;
		input reg [127:0] addr;
		input reg [2:0] size;
		input reg [7:0] len;
		input reg [1:0] burst;
		input reg [15:0] strobe_width;
		input reg [15:0] i_beat;
		if (i_beat == 0)
			axi_pkg_beat_upper_byte = (axi_pkg_aligned_addr(addr, size) + (axi_pkg_num_bytes(size) - 1)) - ((addr / strobe_width) * strobe_width);
		else
			axi_pkg_beat_upper_byte = (axi_pkg_beat_lower_byte(addr, size, len, burst, strobe_width, i_beat) + axi_pkg_num_bytes(size)) - 1;
	endfunction
